alter table public.hms_guest_documents enable row level security; alter table public.hms_guest_deposits enable row level security; alter table public.hms_folio_payments enable row level security; alter table public.hms_maintenance_tasks enable row level security; alter table public.hms_night_audits enable row level security; alter table public.crm_workflow_queue enable row level security; alter table public.crm_forecast_points enable row level security;
do $$ declare t text; begin foreach t in array array['hms_guest_documents','hms_guest_deposits','hms_folio_payments','hms_maintenance_tasks','hms_night_audits'] loop execute format('drop policy if exists tenant_access on public.%I',t); execute format('create policy tenant_access on public.%I for all to authenticated using(restaurant_id=public.anaira_current_restaurant_id() or public.anaira_current_is_super_admin()) with check(restaurant_id=public.anaira_current_restaurant_id() or public.anaira_current_is_super_admin())',t); end loop; foreach t in array array['crm_workflow_queue','crm_forecast_points'] loop execute format('drop policy if exists tenant_access on public.%I',t); execute format('create policy tenant_access on public.%I for all to authenticated using(tenant_id=public.anaira_current_restaurant_id() or public.anaira_current_is_super_admin()) with check(tenant_id=public.anaira_current_restaurant_id() or public.anaira_current_is_super_admin())',t); end loop; end $$;
